Looking at this task, I need to add a `create_invoice_handler` function to handle POST /invoices requests. The handler should:
1. Extract id and items from the request body
2. Create LineItem objects (which will validate qty via `__post_init__`)
3. Create and persist an Invoice with the user as the customer
4. Return 201 with the invoice id and created date on success
5. Return 400 with an error code on any failure

I'll follow the same error-handling pattern as `get_invoice_handler` and add the necessary imports.

### invoicing/api.py
```python
from .errors import InvoiceError
from .invoice import Invoice, LineItem
from .money import format_inr


def _status(err):
    return {"NOT_FOUND": 404, "FORBIDDEN": 403}.get(err.code, 400)


def get_invoice_handler(service, invoice_id, user):
    """GET /invoices/{id}: returns (status, body)."""
    try:
        inv = service.get(invoice_id, user)
        total = service.total(invoice_id, user)
    except InvoiceError as e:
        return _status(e), {"error": e.code}
    return 200, {
        "id": inv.id,
        "customer": inv.customer,
        "created": inv.created.isoformat(),
        "total": total,
        "total_display": format_inr(total),
    }


def create_invoice_handler(service, user, body):
    """POST /invoices: returns (status, body)."""
    try:
        invoice_id = body["id"]
        items_data = body["items"]

        items = [LineItem(item["sku"], item["qty"], item["unit_paise"]) for item in items_data]

        invoice = Invoice(invoice_id, user, items)
        service.create(invoice)

        return 201, {"id": invoice.id, "created": invoice.created.isoformat()}
    except InvoiceError as e:
        return _status(e), {"error": e.code}
    except (KeyError, TypeError):
        return 400, {"error": "BAD_AMOUNT"}
